// Medical Reading Practice Test 2. Original questions written for Valus for the five 2026–27 HOSA books.
// Like the Valus Medical Reading lessons, these questions do not claim to report specific chapters,
// passages or patients from the copyrighted books. They test the background science, concepts and
// reading-analysis skills each book draws on; students should study the books themselves for details.
import {q, mix} from './q.js';
const CA='Crisis Averted (Rivers)', TB='Everything Is Tuberculosis (Green)', FR='Fragmented (Yurkiewicz)', NP='The Next Patient (Grant)', GR='Grit (Duckworth)';
const CDC='CDC', WHO='World Health Organization', AHRQ='Agency for Healthcare Research and Quality', DUCK='Duckworth et al., grit research publications', VAL='Valus Medical Reading lessons';

export default {
 id:'medical-reading-2',
 event:'Medical Reading',
 title:'Practice Test 2',
 subtitle:'Background and ideas behind the five assigned books',
 minutes:60,
 sources:'the five assigned books’ subject areas, with background from the CDC, WHO, AHRQ and published grit research (study the books for chapter details)',
 plan:[{area:CA,weight:20},{area:TB,weight:20},{area:FR,weight:20},{area:NP,weight:20},{area:GR,weight:20}],
 questions:mix([
  q(CA,'What distinguishes a pandemic from an epidemic?','It spreads across several countries or continents',['It always has a higher death rate than an epidemic','It is caused only by new influenza viruses','It affects only one community at a time'],'A','An epidemic is an increase in cases above expected levels in an area; a pandemic is an epidemic that has spread across countries or continents.',CDC),
  q(CA,'What does an epidemic curve show?','The number of cases by date of illness onset',['The geographic spread of cases on a map','The age and sex of every case-patient','The cost of the outbreak response over time'],'B','An epidemic curve plots cases over time, revealing the outbreak’s pattern, likely exposure period and whether control measures are working.',CDC),
  q(CA,'Health officials report that the effective reproduction number (Rt) has fallen to 0.8. What does this suggest?','The number of new cases is likely shrinking',['The disease has been fully eliminated','Each case now infects about 8 people','The outbreak is growing faster than before'],'C','When each case infects fewer than one other person on average, transmission chains die out and the outbreak declines.',CDC),
  q(CA,'A disease has an R₀ of 4. Using the formula 1 − 1/R₀, about what share of people must be immune to stop sustained spread?','75%',['25%','40%','96%'],'D','1 − 1/4 = 0.75, so about 75% of the population must be immune; more contagious diseases need higher immunity levels.',CDC),
  q(CA,'What is the incubation period of an infectious disease?','The time from infection to the onset of symptoms',['The time a patient stays in the hospital','The time from symptoms until full recovery','The time a pathogen survives on surfaces'],'A','Knowing the incubation period helps investigators find the likely exposure time and set how long exposed people should be watched.',CDC),
  q(CA,'In an outbreak, 400 confirmed cases include 20 deaths. What is the case fatality rate?','5%',['2%','8%','20%'],'B','Case fatality rate = deaths ÷ confirmed cases × 100 = 20 ÷ 400 × 100 = 5%. Missed mild cases can make it look higher than it is.',CDC),
  q(CA,'Forecasters estimate today’s case count while accounting for reporting delays. What is this called?','Nowcasting',['Backcasting','Contact tracing','Herd immunity'],'C','Because reports lag behind infections, nowcasting estimates the current situation so leaders do not act on outdated numbers.',CDC),
  q(CA,'Why is wastewater surveillance useful for detecting outbreaks?','It can show rising infection before cases are reported',['It identifies each infected person by name and address','It replaces the need for testing sick patients','It measures only bacteria spread by contaminated food'],'D','People shed pathogens in waste whether or not they get tested, so wastewater trends can give communities early warning.',CDC),
  q(CA,'How does isolation differ from quarantine?','Isolation separates sick people; quarantine separates exposed people',['Isolation is voluntary; quarantine always requires a court order','Isolation is used only for animals; quarantine for people','There is no difference between the two terms'],'A','Isolation keeps people who are infected away from others; quarantine restricts movement of those exposed who may become sick.',CDC),
  q(CA,'Which evidence would best support a claim that a school closure reduced cases?','Fewer cases than in similar areas that stayed open',['A quote from an official who ordered the closure','A rise in cases in the month before the closure','Positive comments from parents on social media'],'B','A strong claim needs a comparison group. Similar places without the intervention help estimate the counterfactual.',VAL),
  q(TB,'Why is Mycobacterium tuberculosis identified with an acid-fast stain?','Its waxy cell wall resists ordinary stains',['It has no cell wall, so it cannot be Gram stained','It is a virus too small for light microscopes','It only grows in highly acidic stomach fluid'],'C','The waxy cell wall holds the stain after an acid-alcohol wash, so the bacilli appear red on an acid-fast (Ziehl–Neelsen) smear.',CDC),
  q(TB,'Which four drugs make up the standard first-line regimen for drug-susceptible TB disease?','Rifampin, isoniazid, pyrazinamide and ethambutol',['Penicillin, amoxicillin, cephalexin and vancomycin','Insulin, metformin, aspirin and heparin','Acyclovir, oseltamivir, zidovudine and nevirapine'],'D','The “RIPE” drugs are given together so that bacteria resistant to one drug are killed by the others.',CDC),
  q(TB,'A positive TB skin test or interferon-gamma release assay (IGRA) shows what?','That a person has been infected with TB bacteria',['That a person has active, contagious TB disease','That a person is immune and cannot get TB','That a person’s TB is resistant to drugs'],'A','These tests detect infection but cannot tell latent infection from disease; a chest X-ray and sputum tests are needed.',CDC),
  q(TB,'Why was tuberculosis historically called “consumption”?','Severe wasting seemed to consume the body',['It spread mainly through food','It was linked to heavy alcohol use','It was treated by eating large meals'],'B','Advanced TB causes wasting, fever, night sweats and a chronic cough, so patients appeared to be consumed by the disease.',VAL),
  q(TB,'What type of hospital room is used for a patient with suspected infectious TB?','A negative-pressure airborne infection isolation room',['A positive-pressure protective environment room','A standard semi-private room with the door open','An operating room with laminar airflow'],'C','Negative pressure keeps contaminated air from flowing into hallways, and staff wear fit-tested N95 respirators.',CDC),
  q(TB,'Why does HIV infection greatly increase the risk of developing TB disease?','HIV weakens immune control of latent TB',['HIV and TB are caused by the same organism','TB drugs make people more likely to catch HIV','HIV makes the TB skin test always negative'],'A','Without effective immune control, latent infection can progress to active disease, so TB is a leading cause of death in people with HIV.',WHO),
  q(TB,'Which scientist identified the bacterium that causes tuberculosis in 1882?','Robert Koch',['Louis Pasteur','Alexander Fleming','Edward Jenner'],'D','Koch announced his discovery on March 24, 1882, which is why World TB Day is observed on March 24 each year.',WHO),
  q(TB,'Which social conditions most increase the spread of TB in a community?','Crowded housing, poverty and malnutrition',['High rates of vaccination and clean water','Low population density and good nutrition','Wide access to free primary care'],'B','Crowding increases airborne exposure, while poverty and malnutrition weaken immunity and limit access to diagnosis and treatment.',WHO),
  q(TB,'Why must treatment for drug-susceptible TB continue for at least six months?','The bacteria grow slowly and some stay dormant',['The drugs need six months to be absorbed','Patients remain contagious for the whole six months','Shorter courses are not allowed by insurance'],'C','Stopping early leaves surviving bacteria that can cause relapse and may become drug resistant, which is why adherence matters.',CDC),
  q(TB,'Which antibiotic, discovered in 1943, was the first effective drug treatment for TB?','Streptomycin',['Penicillin','Rifampin','Isoniazid'],'D','Streptomycin began the antibiotic era for TB, but resistance quickly appeared when it was used alone, leading to combination therapy.',WHO),
  q(FR,'What is medication reconciliation?','Comparing medication lists at each transition of care',['Billing an insurer for each prescription filled','Ordering the cheapest version of every drug','Switching all medicines to a single pharmacy'],'A','Reconciling lists at admission, transfer and discharge catches omissions, duplications and interactions that cause harm.',AHRQ),
  q(FR,'In health information technology, what does interoperability mean?','Different systems can exchange and use each other’s data',['One hospital uses the same software in every department','Patients can pay bills online through a portal','Records are kept only on paper for safety'],'B','Without interoperability, information gets stuck in separate systems, so clinicians may lack test results or histories from other sites.',AHRQ),
  q(FR,'What is the main role of a patient navigator or care coordinator?','Guiding patients through referrals and services',['Performing surgery when specialists are unavailable','Approving or denying insurance claims','Writing prescriptions for chronic conditions'],'C','Navigators help patients move across a complex system, closing gaps in follow-up that fragmented care can leave behind.',AHRQ),
  q(FR,'How can the hospitalist model contribute to fragmented care?','The inpatient doctor is not the regular doctor',['Hospitalists are not licensed to admit patients','Hospitalists see patients only after discharge','Hospitalists are required to work alone'],'D','Hospitalists manage inpatient care efficiently, but each handoff to and from the primary care doctor is a point where information can be lost.',AHRQ),
  q(FR,'What is the purpose of a discharge summary?','To tell the next clinician what happened and what comes next',['To give the insurer the itemized bill for the stay','To record the patient’s satisfaction survey','To list the hospital staff on duty during the stay'],'A','A timely, clear discharge summary helps the next clinician continue care; delays or missing details are a common source of errors.',AHRQ),
  q(FR,'What is a patient-centered medical home (PCMH)?','A primary care model that coordinates all care',['A nursing home run by the patient’s family','A hospital unit for patients without insurance','A home health agency that provides only meals'],'B','The PCMH model places a primary care team at the center of coordination, with comprehensive, accessible and continuous care.',AHRQ),
  q(FR,'An author presents an opposing view and then explains why it is wrong. What is the second part called?','A rebuttal',['A warrant','A thesis','An anecdote'],'C','Addressing a counterargument and then rebutting it makes an argument more persuasive because it shows the author considered other views.',VAL),
  q(FR,'What is the main limitation of using a single patient’s story as evidence for a system-wide problem?','One case may not show how common a problem is',['Stories cannot be used in nonfiction writing','A single story is always partly fictional','Patient stories are too emotional to be useful'],'D','Anecdotes illustrate a problem vividly, but readers should look for data showing how common it is before generalizing.',VAL),
  q(FR,'Under HIPAA, may a hospital share a patient’s records with the patient’s other treating clinicians without a separate authorization?','Yes, sharing for treatment purposes is permitted',['No, every disclosure requires written permission','Only if the patient is over age 65','Only after the patient pays the bill in full'],'A','HIPAA permits disclosures for treatment, payment and operations, so privacy rules alone should not block coordination between treating clinicians.',AHRQ),
  q(FR,'Which question best tests whether an author’s solution to fragmented care is realistic?','What would it cost, and who would do it?',['Is the author a highly skilled storyteller?','Does the book have a memorable title?','Did the author enjoy writing the book?'],'B','Evaluating a proposal means checking feasibility—costs, responsibilities and trade-offs—not just whether the problem is described well.',VAL),
  q(NP,'What is a differential diagnosis?','A list of conditions that could explain symptoms',['The final confirmed diagnosis after testing','A diagnosis made by two different doctors','The difference between two lab results over time'],'A','Clinicians build a differential and then use history, exam and tests to narrow it, keeping dangerous possibilities in view.',VAL),
  q(NP,'Why do emergency physicians use a “worst-first” approach to the differential diagnosis?','To rule out deadly causes before common ones',['To order the most expensive tests first','To admit every patient to the hospital','To avoid examining the patient directly'],'B','A chest pain patient may most likely have a minor cause, but conditions such as heart attack or aortic dissection must be excluded first.',VAL),
  q(NP,'A doctor who just treated a rare disease starts seeing it in many new patients. Which bias is this?','Availability bias',['Anchoring bias','Confirmation bias','Framing bias'],'C','Recent or memorable cases come to mind easily, making a diagnosis seem more likely than its true frequency.',AHRQ),
  q(NP,'A label such as “drug seeking” passes from clinician to clinician until no one questions it. What is this called?','Diagnostic momentum',['Premature closure','Outcome bias','Base-rate neglect'],'D','Diagnostic momentum occurs when an early label gains authority with each handoff, so new information is not used to reconsider it.',AHRQ),
  q(NP,'Why does pretest probability matter when interpreting a test result?','The same result means more in a high-risk patient',['It decides which laboratory should run the test','It replaces the need for a physical examination','It estimates how much the test will cost the patient'],'A','By Bayesian reasoning, a positive result in a low-risk patient is more likely to be a false positive than in a high-risk patient.',AHRQ),
  q(NP,'A highly sensitive test is negative. What does this usually allow a clinician to do?','Rule out the condition with confidence',['Confirm that the condition is present','Stop all further patient monitoring','Disregard the patient’s reported symptoms'],'B','A sensitive test rarely misses disease, so a negative result helps rule it out (“SnOut”); a specific positive helps rule it in (“SpIn”).',AHRQ),
  q(NP,'Why are patients who “leave without being seen” a safety concern in crowded emergency departments?','Some may have serious, untreated conditions',['They always return the next day for care','They lower hospital costs without any risk','They are counted as admitted patients'],'C','Long waits drive some patients to leave before evaluation, and a few may have time-sensitive illnesses that are missed.',AHRQ),
  q(NP,'What is the purpose of a “diagnostic time-out”?','To pause and ask what else the diagnosis could be',['To stop all care until a specialist arrives','To end the shift handoff early','To delay treatment while forms are completed'],'D','A brief pause to reconsider the working diagnosis is a metacognitive strategy that can counter anchoring and premature closure.',AHRQ),
  q(NP,'Under the Emergency Severity Index, which patient is ESI level 1?','A patient who needs immediate life-saving care',['A stable patient who needs no resources','A patient with a minor ankle sprain and mild pain','A patient waiting for a prescription refill'],'A','ESI 1 patients, such as those in cardiac arrest or severe respiratory distress, need immediate intervention; ESI 5 need no resources.',AHRQ),
  q(NP,'A doctor’s reasonable decision is judged as poor only because the patient had a bad result. What is this bias?','Outcome bias',['Availability bias','Representativeness bias','Search satisficing'],'B','Outcome bias judges decisions by results instead of by the information available when they were made, which can distort learning.',VAL),
  q(GR,'In Duckworth’s West Point research, what did grit predict better than the academy’s overall admissions score?','Which cadets would complete summer training',['Which cadets would earn the highest grades','Which cadets had the most athletic ability','Which cadets would become generals'],'C','Grit predicted completing the demanding summer training better than the Whole Candidate Score, though it did not explain everything.',DUCK),
  q(GR,'In National Spelling Bee research, how did grittier spellers tend to advance further?','By spending more time on deliberate practice',['By relying on natural memory talent alone','By competing in more bees each year','By studying only the night before'],'D','Grit predicted accumulating more deliberate practice, which in turn predicted better performance in the final rounds.',DUCK),
  q(GR,'A 2017 meta-analysis by Credé and colleagues found which part of grit was more predictive of performance?','Perseverance of effort',['Consistency of interests','Natural talent','IQ'],'A','The perseverance facet predicted performance better than consistency of interests, raising questions about combining them into one score.',DUCK),
  q(GR,'In Duckworth’s model, how does effort contribute to achievement?','It counts twice, in building and using skill',['It matters only for people with little talent','It counts once, the same as talent','It has no measurable role in achievement'],'B','Duckworth proposes talent × effort = skill and skill × effort = achievement, so effort enters the equation twice.',VAL),
  q(GR,'Which four psychological assets does Duckworth describe as building grit?','Interest, practice, purpose and hope',['Talent, luck, money and age','Talent, luck, coaching and support','Popularity, status, wealth and fame'],'C','Grit grows from developing an interest, practicing deliberately, connecting work to purpose and maintaining hope after setbacks.',VAL),
  q(GR,'How does grit differ from self-control in Duckworth’s research?','Grit sustains long-term goals; self-control resists temptations',['Grit applies to school; self-control applies to sports','They are identical traits with different names','Self-control matters only in early childhood'],'D','Self-control helps resist momentary temptations, while grit sustains effort and interest toward one top-level goal over years.',DUCK),
  q(GR,'A study reports a small effect size for grit predicting grades. What does this mean?','Grit explains only a modest part of grade differences',['Grit has no relationship with grades at all','The study used too few students to be counted','Grit causes grades to rise slightly for all students'],'A','Effect size shows the strength of a relationship; a small one means many other factors also matter, and it says nothing about causation.',DUCK),
  q(GR,'In Duckworth’s goal hierarchy, what sits at the top?','One ultimate goal that gives others meaning',['A long list of equally important tasks','Short daily goals with no larger purpose','Goals chosen by others for the person'],'B','Lower-level goals serve as means to the top-level goal; gritty people can swap lower goals while keeping the ultimate aim.',VAL),
  q(GR,'A grit questionnaire predicts persistence but correlates strongly with conscientiousness. Which question does this raise?','Whether grit is distinct from an existing trait',['Whether the questionnaire was printed correctly','Whether the students enjoyed taking the test','Whether the test has too many items'],'C','Construct validity asks whether a measure captures a unique concept; heavy overlap suggests grit may largely restate conscientiousness.',DUCK),
  q(GR,'Which is a common critique of emphasizing grit in schools?','It may overlook barriers such as poverty',['It makes students too interested in schoolwork','It requires expensive laboratory equipment','It applies only to athletes and musicians'],'D','Critics argue that focusing on individual persistence can shift attention away from structural problems that also shape success.',VAL)
 ],4331)
};
